import pytest
import torch

import flag_gems

from .base import Benchmark


def _valid_dense(shape, dtype, device):
    rows, cols = shape
    ksparse = 2 if dtype == torch.float32 else 4
    keep = ksparse // 2
    x = torch.zeros(shape, dtype=dtype, device=device)
    for g0 in range(cols // ksparse):
        base = g0 * ksparse
        slots = [(g0 + i) % ksparse for i in range(keep)]
        if dtype.is_floating_point:
            vals = torch.randn(rows, keep, dtype=dtype, device=device)
        else:
            vals = torch.randint(1, 128, (rows, keep), device=device).to(dtype)
        x[:, base + slots[0]] = vals[:, 0]
        if keep == 2:
            x[:, base + slots[1]] = vals[:, 1]
    return x


class ToSparseSemiStructuredBenchmark(Benchmark):
    def get_input_iter(self, cur_dtype):
        # On Ampere the native 2:4 CUTLASS kernel mis-sizes the packed buffer
        # for bf16 at 2048x2048 (returns two elements short, so aten's reshape
        # to (2048, 1024) fails). int8 shares that 2:4 path, so cap both at
        # 1024; fp16 (2:4) and fp32 (1:2) are unaffected and keep 2048.
        shapes = [(64, 64), (256, 256), (1024, 1024), (2048, 2048)]
        if cur_dtype in (torch.bfloat16, torch.int8):
            shapes = shapes[:-1]
        for shape in shapes:
            yield (_valid_dense(shape, cur_dtype, self.device),)


@pytest.mark.to_sparse_semi_structured
def test_to_sparse_semi_structured():
    bench = ToSparseSemiStructuredBenchmark(
        op_name="to_sparse_semi_structured",
        torch_op=torch.ops.aten._to_sparse_semi_structured,
        gems_op=flag_gems.to_sparse_semi_structured,
        dtypes=[torch.float16, torch.bfloat16, torch.float32, torch.int8],
    )
    bench.run()
